const version=++panel.historyRequestId,seconds=panel.seconds,contract=panel.contract;let displayed=[];
const stillCurrent=()=>version===panel.historyRequestId&&seconds===panel.seconds&&String(panel.contract.token)===String(contract.token)&&chartManager.panels.has(panel.key);
const candleEpoch=c=>{const numeric=Number(c?.time);return Number.isFinite(numeric)?numeric:Date.parse(String(c?.time||''))/1000};const mergeCandles=(...groups)=>[...new Map(groups.flat().map(c=>[candleEpoch(c),c]).filter(([time])=>Number.isFinite(time))).entries()].sort((a,b)=>a[0]-b[0]).map(([,c])=>c);
const interval=historyInterval(seconds),{from,to}=chartHistoryRange();
const fetchCandles=async(fromDate,toDate)=>{const result=await angelPost('/api/angel/history',{token:String(contract.token),exchange:contract.exchange||'NSE',exchangeType:contract.exchangeType,from:fromDate,to:toDate,interval});if(String(result.token)!==String(contract.token))throw new Error('Historical data response did not match this option contract.');return Array.isArray(result.candles)?result.candles:[]};
const applyHistory=(candles,status,source,fit=false)=>{if(!stillCurrent()||!candles?.length)return;displayed=mergeCandles(displayed,candles);chartManager.setData(panel.key,displayed,{fit,status,source})};
