function applyLiveQuote(quote,candle,marketCandle){if(!quote)return;angelState.quotes=angelState.quotes||{};angelState.quotes[quote.token]=quote;if(pendingOptionToken===String(quote.token))$('optionQuickPrice').textContent=fmtPrice(quote.ltp);for(const btn of $('chainTable').querySelectorAll('[data-token]'))if(btn.dataset.token===String(quote.token))btn.innerHTML=optionPremiumMarkup(quote);const contract=(angelState.chain||[]).find(c=>String(c.token)===String(quote.token)),row=contract&&$('chainTable').querySelector(`[data-token="${quote.token}"]`)?.closest('tr');if(row){const changeCell=row.cells[contract.side==='CE'?0:4];if(changeCell)changeCell.innerHTML=optionChangeMarkup(quote);updateChainSummary()}const tokens=angelState.indexTokens||{};if(String(tokens.NIFTY||'')===String(quote.token)){$('niftySpot').textContent=fmtPrice(quote.ltp);$('niftySpotTime').textContent='AngelOne Live Spot Tick'}if(String(tokens.SENSEX||'')===String(quote.token)){$('sensexSpot').textContent=fmtPrice(quote.ltp);$('sensexSpotTime').textContent='AngelOne Live Spot Tick'}if(String(angelState.contract?.token||'')===String(quote.token))$('optionQuote').textContent=fmtPrice(quote.ltp);queueChartUpdate(quote,candle,marketCandle);renderPositionDesk(quote);renderPositionHistory()}
